export type ParsedDrawInstruction<
  TProgram extends string = typeof GUMBALL_GUARD_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Gumball Guard account. */
    gumballGuard: TAccountMetas[0];
    /**
     * Gumball Machine program account.
     *
     */
    gumballMachineProgram: TAccountMetas[1];
    /** Gumball machine account. */
    gumballMachine: TAccountMetas[2];
    /** Payer for the mint (SOL) fees. */
    payer: TAccountMetas[3];
    /** Minter account for validation and non-SOL fees. */
    buyer: TAccountMetas[4];
    /**
     * Token Metadata program.
     *
     */
    tokenMetadataProgram: TAccountMetas[5];
    /** SPL Token program. */
    splTokenProgram: TAccountMetas[6];
    /** System program. */
    systemProgram: TAccountMetas[7];
    /**
     * Instructions sysvar account.
     *
     */
    sysvarInstructions: TAccountMetas[8];
    /**
     * SlotHashes sysvar cluster data.
     *
     */
    recentSlothashes: TAccountMetas[9];
    gumballEventAuthority: TAccountMetas[10];
  };
  data: DrawInstructionData;
};

export function parseDrawInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedDrawInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      }
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      gumballGuard: getNextAccount(),
      gumballMachineProgram: getNextAccount(),
      gumballMachine: getNextAccount(),
      payer: getNextAccount(),
      buyer: getNextAccount(),
      tokenMetadataProgram: getNextAccount(),
      splTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      sysvarInstructions: getNextAccount(),
      recentSlothashes: getNextAccount(),
      gumballEventAuthority: getNextAccount(),
    },
    data: getDrawInstructionDataDecoder().decode(instruction.data),
  };
}
